<?php
require_once __DIR__.'/support-activity.php';
require_once __DIR__.'/support-report.php';
require_once __DIR__.'/support-performance.php';
require_once __DIR__.'/support-satisfaction.php';
// Central support domain. Never accepts authority from a browser-supplied role.
function supportText($value,$max,$required=true){if(!is_string($value)||mb_strlen($value)>$max||($required&&trim($value)===''))throw new InvalidArgumentException('Revisa los campos y su longitud.');return trim($value);}
function supportNow(){return (new DateTimeImmutable('now',new DateTimeZone('America/Lima')))->format('Y-m-d H:i:s');}
function supportQuery($db,$sql,$params=[]){$s=$db->prepare($sql);$s->execute($params);return $s;}
function supportValidatedSql(){return "EXISTS(SELECT 1 FROM support_satisfaction_surveys validation WHERE validation.tenant_id=t.tenant_id AND validation.ticket_id=t.id AND validation.respondent_id=t.requester_id AND validation.solved=1 AND validation.speed BETWEEN 1 AND 5 AND validation.treatment BETWEEN 1 AND 5 AND validation.solution BETWEEN 1 AND 5 AND validation.cycle=(SELECT 1+COUNT(*) FROM support_ticket_status_history cycle_history WHERE cycle_history.tenant_id=t.tenant_id AND cycle_history.ticket_id=t.id AND cycle_history.next_status='reopened'))";}
function supportRequireCustomerRating($db,$identity,$ticket){
 if((int)$ticket['requester_id']!==$identity['principal'])throw new InvalidArgumentException('Solo el cliente solicitante puede confirmar el cierre de su atención.');
 $rating=supportQuery($db,"SELECT id FROM support_satisfaction_surveys WHERE tenant_id=? AND ticket_id=? AND respondent_id=? AND solved=1 AND speed BETWEEN 1 AND 5 AND treatment BETWEEN 1 AND 5 AND solution BETWEEN 1 AND 5 AND cycle=(SELECT 1+COUNT(*) FROM support_ticket_status_history WHERE tenant_id=? AND ticket_id=? AND next_status='reopened')",[$ticket['tenant_id'],$ticket['id'],$identity['principal'],$ticket['tenant_id'],$ticket['id']])->fetchColumn();
 if(!$rating)throw new InvalidArgumentException('El cliente debe validar que la solución funciona y calificar de 1 a 5 estrellas antes de cerrar la atención.');
}
function supportAudit($db,$i,$action,$id,$details=[]){supportQuery($db,'INSERT INTO support_audit_logs(tenant_id,actor_id,action,entity_type,entity_id,metadata_json,created_at) VALUES(?,?,?,?,?,?,?)',[$i['tenant'],$i['principal'],$action,'ticket',$id,json_encode($details,JSON_UNESCAPED_UNICODE),supportNow()]);}
function supportNotify($db,$tenant,$ticket,$kind,$actor,$internal=false){
 $t=supportQuery($db,'SELECT requester_id,technician_id FROM support_tickets WHERE tenant_id=? AND id=?',[$tenant,$ticket])->fetch(PDO::FETCH_ASSOC);if(!$t)return;
 $recipients=supportQuery($db,"SELECT DISTINCT p.id FROM support_principals p JOIN support_memberships m ON m.principal_id=p.id AND m.active=1 WHERE p.active=1 AND (m.role='superadmin' OR (m.tenant_id=? AND (m.role='supervisor' OR (m.role='technician' AND (? IS NULL OR p.id=?)))))",[$tenant,$t['technician_id'],$t['technician_id']])->fetchAll(PDO::FETCH_COLUMN);
 if(!$internal)$recipients[]=$t['requester_id'];foreach(array_unique($recipients) as $recipient)if((int)$recipient!==(int)$actor)supportQuery($db,'INSERT INTO support_notifications(tenant_id,ticket_id,recipient_id,kind,created_at) VALUES(?,?,?,?,?)',[$tenant,$ticket,$recipient,$kind,supportNow()]);
}
function supportAssignmentNotice($db,$ticket,$technician,$now){
 if((int)$ticket['technician_id']===(int)$technician)return;
 $name=supportQuery($db,'SELECT external_user_id FROM support_principals WHERE id=?',[$technician])->fetchColumn();
 $deadline=supportQuery($db,'SELECT expected_resolution_at FROM support_tickets WHERE id=?',[$ticket['id']])->fetchColumn();
 $body='Aviso automático: '.$name.' es ahora responsable de tu atención. '.($deadline?'Hora estimada de solución: '.$deadline.' (Lima). ':'El técnico confirmará el tiempo estimado. ').'Puedes escribirle en esta conversación; te avisaremos cuando responda. Gracias por tu paciencia.';
 $hex=bin2hex(random_bytes(16));$operation=substr($hex,0,8).'-'.substr($hex,8,4).'-'.substr($hex,12,4).'-'.substr($hex,16,4).'-'.substr($hex,20);
 supportQuery($db,"INSERT INTO support_ticket_messages(tenant_id,ticket_id,author_id,visibility,body,operation_uuid,created_at) VALUES(?,?,?,'public',?,?,?)",[$ticket['tenant_id'],$ticket['id'],$technician,$body,$operation,$now]);
 // An automatic acknowledgment never counts as the technician's first public reply.
}
function supportEstimate($db,$ticket,$payload,$now){
 if(!array_key_exists('estimated_minutes',$payload)||$payload['estimated_minutes']==='')return;
 $minutes=filter_var($payload['estimated_minutes'],FILTER_VALIDATE_INT);
 if(!$minutes||$minutes<1||$minutes>43200)throw new InvalidArgumentException('Indica una estimación entre 1 y 43200 minutos.');
 $deadline=(new DateTimeImmutable($now,new DateTimeZone('America/Lima')))->modify('+'.$minutes.' minutes')->format('Y-m-d H:i:s');
 supportQuery($db,'UPDATE support_tickets SET estimated_minutes=?,expected_resolution_at=? WHERE id=?',[$minutes,$deadline,$ticket['id']]);
}
function supportScope($db,$i,$alias='t'){
 if($i['superadmin'])return ['1=1',[]];
 $roles=supportQuery($db,'SELECT tenant_id,role FROM support_memberships WHERE principal_id=? AND active=1',[$i['principal']])->fetchAll(PDO::FETCH_ASSOC);$parts=[];$params=[];
 foreach($roles as $r){if(in_array($r['role'],['supervisor','company_admin'],true)){$parts[]="$alias.tenant_id=?";$params[]=$r['tenant_id'];}elseif($r['role']==='technician'){$parts[]="($alias.tenant_id=? AND ($alias.technician_id=? OR ($alias.technician_id IS NULL AND $alias.status IN ('new','reopened','escalated'))))";array_push($params,$r['tenant_id'],$i['principal']);}elseif($r['role']==='requester'){$parts[]="($alias.tenant_id=? AND $alias.requester_id=?)";array_push($params,$r['tenant_id'],$i['principal']);}}
 return [$parts?'('.implode(' OR ',$parts).')':'1=0',$params];
}
function supportRole($db,$i,$tenant){if($i['superadmin'])return 'superadmin';$roles=supportQuery($db,'SELECT role FROM support_memberships WHERE tenant_id=? AND principal_id=? AND active=1',[$tenant,$i['principal']])->fetchAll(PDO::FETCH_COLUMN);foreach(['supervisor','technician','company_admin','requester'] as $role)if(in_array($role,$roles,true))return $role;throw new InvalidArgumentException('Acceso no disponible.');}
function supportTicket($db,$i,$id,$lock=false){[$scope,$params]=supportScope($db,$i);$t=supportQuery($db,'SELECT t.*,assignee.external_user_id assigned_name,requester.external_user_id requester_name FROM support_tickets t LEFT JOIN support_principals assignee ON assignee.id=t.technician_id JOIN support_principals requester ON requester.id=t.requester_id JOIN support_tenants tenant ON tenant.id=t.tenant_id AND tenant.active=1 JOIN support_installations inst ON inst.id=tenant.installation_id AND inst.active=1 WHERE t.id=? AND '.$scope.($lock?' FOR UPDATE':''),array_merge([(int)$id],$params))->fetch(PDO::FETCH_ASSOC);if(!$t)throw new InvalidArgumentException('Ticket no disponible.');return $t;}
function supportIdentity($db,$installation,$externalUser,$externalCompany,$name){
 $tenant=supportQuery($db,'SELECT t.id FROM support_tenants t JOIN support_installations i ON i.id=t.installation_id WHERE t.installation_id=? AND t.external_company_id=? AND t.active=1 AND i.active=1',[$installation,$externalCompany])->fetchColumn();if(!$tenant)throw new InvalidArgumentException('Empresa no habilitada para soporte.');
 supportQuery($db,'INSERT INTO support_principals(installation_id,external_user_id) VALUES(?,?) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id)',[$installation,$externalUser]);
 $p=supportQuery($db,'SELECT id,active FROM support_principals WHERE installation_id=? AND external_user_id=?',[$installation,$externalUser])->fetch(PDO::FETCH_ASSOC);if(!$p['active'])throw new InvalidArgumentException('Acceso deshabilitado.');
 supportQuery($db,"INSERT IGNORE INTO support_memberships(tenant_id,principal_id,role) VALUES(?,?,'requester')",[$tenant,$p['id']]);
 $super=(bool)supportQuery($db,"SELECT 1 FROM support_memberships WHERE principal_id=? AND role='superadmin' AND active=1 LIMIT 1",[$p['id']])->fetchColumn();
 return ['principal'=>(int)$p['id'],'tenant'=>(int)$tenant,'superadmin'=>$super,'user'=>$externalUser,'name'=>$name,'installation'=>(int)$installation];
}
function supportDispatch($db,$i,$action,$p=[]){
