  $tenants=$i['superadmin']?supportQuery($db,'SELECT t.id,i.origin_https,t.external_company_id,t.active,i.installation_uuid FROM support_tenants t JOIN support_installations i ON i.id=t.installation_id ORDER BY t.id')->fetchAll(PDO::FETCH_ASSOC):supportQuery($db,'SELECT DISTINCT t.id,i.origin_https,t.external_company_id,t.active FROM support_tenants t JOIN support_installations i ON i.id=t.installation_id JOIN support_memberships m ON m.tenant_id=t.id WHERE m.principal_id=? AND m.active=1 AND t.active=1 AND i.active=1',[$i['principal']])->fetchAll(PDO::FETCH_ASSOC);
  $i['tenants']=$tenants;$i['roles']=supportQuery($db,'SELECT tenant_id,role FROM support_memberships WHERE principal_id=? AND active=1',[$i['principal']])->fetchAll(PDO::FETCH_ASSOC);$i['categories']=supportQuery($db,'SELECT * FROM support_categories ORDER BY name')->fetchAll(PDO::FETCH_ASSOC);return $i;
 }
 if($action==='tickets'){
  [$scope,$args]=supportScope($db,$i);$where=[$scope,'tenant.active=1','inst.active=1'];
  $archive=$p['archived']??'active';if(!in_array($archive,['active','only','all'],true))throw new InvalidArgumentException('Filtro de archivo inválido.');if($archive!=='all')$where[]='t.archived_at IS '.($archive==='only'?'NOT ':'').'NULL';
  foreach(['status','priority','category_id','tenant_id','technician_id'] as $field)if(isset($p[$field])&&$p[$field]!==''){$where[]='t.'.$field.'=?';$args[]=$p[$field];}
