  foreach(['from'=>'>=','to'=>'<='] as $key=>$op)if(!empty($p[$key])){if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$p[$key])||!DateTimeImmutable::createFromFormat('!Y-m-d',$p[$key])||DateTimeImmutable::createFromFormat('!Y-m-d',$p[$key])->format('Y-m-d')!==$p[$key])throw new InvalidArgumentException('Fecha no válida.');$where[]='t.created_at '.$op.' ?';$args[]=$p[$key].($key==='from'?' 00:00:00':' 23:59:59');}
  $join=' FROM support_tickets t JOIN support_tenants tenant ON tenant.id=t.tenant_id JOIN support_installations inst ON inst.id=tenant.installation_id WHERE '.implode(' AND ',$where);
  $total=(int)supportQuery($db,'SELECT COUNT(*)'.$join,$args)->fetchColumn();$metrics=supportQuery($db,'SELECT COUNT(DISTINCT t.tenant_id) companies,AVG(TIMESTAMPDIFF(MINUTE,t.created_at,t.first_response_at)) response_minutes,AVG(TIMESTAMPDIFF(MINUTE,t.created_at,t.resolved_at)) resolution_minutes'.$join,$args)->fetch(PDO::FETCH_ASSOC);$byTech=supportQuery($db,"SELECT t.technician_id,(SELECT external_user_id FROM support_principals WHERE id=t.technician_id) technician_name,COUNT(*) total,SUM(t.status IN ('resolved','closed')) resolved".$join.' GROUP BY t.technician_id',$args)->fetchAll(PDO::FETCH_ASSOC);$stats=supportQuery($db,'SELECT t.status,COUNT(*) total'.$join.' GROUP BY t.status',$args)->fetchAll(PDO::FETCH_ASSOC);
  foreach($byTech as &$techRow){$techWhere=$join.' AND t.technician_id <=> ?';$techArgs=array_merge($args,[$techRow['technician_id']]);$timing=supportQuery($db,'SELECT AVG(TIMESTAMPDIFF(MINUTE,t.created_at,t.first_response_at)) response_minutes,AVG(TIMESTAMPDIFF(MINUTE,t.created_at,t.resolved_at)) resolution_minutes'.$techWhere,$techArgs)->fetch(PDO::FETCH_ASSOC);$rating=supportQuery($db,'SELECT AVG((s.speed+s.treatment+s.solution)/3.0) rating,COUNT(*) rating_count FROM support_satisfaction_surveys s JOIN support_tickets t ON t.id=s.ticket_id AND t.tenant_id=s.tenant_id JOIN support_tenants tenant ON tenant.id=t.tenant_id JOIN support_installations inst ON inst.id=tenant.installation_id WHERE s.id=(SELECT MAX(latest.id) FROM support_satisfaction_surveys latest WHERE latest.ticket_id=t.id AND latest.tenant_id=t.tenant_id) AND '.implode(' AND ',$where).' AND t.technician_id <=> ?',$techArgs)->fetch(PDO::FETCH_ASSOC);$techRow=array_merge($techRow,$timing,$rating);}unset($techRow);
  if(!empty($p['before'])){$join.=' AND t.id<?';$args[]=(int)$p['before'];}
  $rows=supportQuery($db,'SELECT t.*,inst.origin_https,(SELECT external_user_id FROM support_principals WHERE id=t.technician_id) assigned_name,(SELECT external_user_id FROM support_principals WHERE id=t.requester_id) requester_name'.$join.' ORDER BY t.id DESC LIMIT 51',$args)->fetchAll(PDO::FETCH_ASSOC);$more=count($rows)>50;if($more)array_pop($rows);return ['tickets'=>$rows,'total'=>$total,'stats'=>$stats,'metrics'=>$metrics,'by_technician'=>$byTech,'next'=>$more?end($rows)['id']:null];
 }
 if($action==='notifications'){
  [$scope,$args]=supportScope($db,$i);$where=" FROM support_notifications n JOIN support_tickets t ON t.id=n.ticket_id AND t.tenant_id=n.tenant_id JOIN support_tenants tenant ON tenant.id=t.tenant_id AND tenant.active=1 JOIN support_installations inst ON inst.id=tenant.installation_id AND inst.active=1 WHERE n.recipient_id=? AND n.read_at IS NULL AND ".$scope." AND (n.kind<>'internal_message' OR ?=1 OR EXISTS(SELECT 1 FROM support_memberships m WHERE m.principal_id=? AND m.tenant_id=t.tenant_id AND m.active=1 AND m.role IN ('technician','supervisor')))";
  $params=array_merge([$i['principal']],$args,[$i['superadmin']?1:0,$i['principal']]);$count=(int)supportQuery($db,'SELECT COUNT(*)'.$where,$params)->fetchColumn();$rows=supportQuery($db,'SELECT n.id,n.ticket_id,n.kind,n.created_at,t.code,t.subject,t.status,t.expected_resolution_at,(SELECT external_user_id FROM support_principals WHERE id=t.technician_id) assigned_name'.$where.' ORDER BY n.id DESC LIMIT 50',$params)->fetchAll(PDO::FETCH_ASSOC);$urgent=supportUrgentQueue($db,$i);return ['unread'=>$count,'notifications'=>$rows,'urgent_tickets'=>$urgent['tickets'],'urgent_total'=>$urgent['total']];
