 if($action==='create'){
  $tenant=(int)($p['tenant_id']??$i['tenant']);supportRole($db,$i,$tenant);if(!supportQuery($db,'SELECT 1 FROM support_tenants t JOIN support_installations inst ON inst.id=t.installation_id WHERE t.id=? AND t.active=1 AND inst.active=1',[$tenant])->fetchColumn())throw new InvalidArgumentException('Empresa deshabilitada.');
