 }
 if(in_array($action,['detail','message','transition','assign','worklog','survey','archive','restore'],true)){
  $write=$action!=='detail';if($write)$db->beginTransaction();$t=supportTicket($db,$i,$p['id']??0,$write);$role=supportRole($db,$i,$t['tenant_id']);$staff=in_array($role,['superadmin','supervisor','technician'],true);$j=$i;$j['tenant']=$t['tenant_id'];
