   $history=supportQuery($db,'SELECT h.*,a.external_user_id actor FROM support_ticket_status_history h JOIN support_principals a ON a.id=h.actor_id WHERE h.tenant_id=? AND h.ticket_id=? ORDER BY h.id',[$t['tenant_id'],$t['id']])->fetchAll(PDO::FETCH_ASSOC);
   $tech=$staff?supportQuery($db,"SELECT DISTINCT a.id,a.external_user_id FROM support_principals a JOIN support_memberships m ON m.principal_id=a.id WHERE m.tenant_id=? AND m.active=1 AND a.active=1 AND m.role IN ('technician','supervisor','superadmin')",[$t['tenant_id']])->fetchAll(PDO::FETCH_ASSOC):[];
   $minutes=(int)supportQuery($db,'SELECT COALESCE(SUM(TIMESTAMPDIFF(MINUTE,started_at,ended_at)),0) FROM support_worklogs WHERE tenant_id=? AND ticket_id=?',[$t['tenant_id'],$t['id']])->fetchColumn();
